module tb_TopModule;
    reg clk;
    reg a;
    wire q;

    TopModule uut (
        .clk(clk),
        .a(a),
        .q(q)
    );

    // Clock generation: 10ns period (5ns high, 5ns low)
    always #5 clk = ~clk;

    initial begin
        clk = 0;
        a = 1'bx;
        #5; // 5ns: clk=1, a=x
        // Replay waveform vectors at each 5ns interval:
        // 5ns: clk=1, a=0
        a = 0; #5;
        // 10ns: clk=0, a=0
        #5;
        // 15ns: clk=1, a=0
        #10;
        // 25ns: clk=1, a=0
        #10;
        // 35ns: clk=1, a=1
        a = 1; #10;
        // 45ns: clk=1, a=1
        #10;
        // 55ns: clk=1, a=1
        #10;
        // 65ns: clk=1, a=1
        #10;
        // 75ns: clk=1, a=1
        #10;
        // 85ns: clk=1, a=1
        #10;
        $display("SELFTEST PASS");
        $finish;
    end

    initial begin
        // Monitor or self-check specific expected values at specific times
        // 0ns: q=x
        // 15ns: q should be 1
        // 45ns: q should be 0
        #15;
        if (q !== 1'b1) begin
            $display("SELFTEST FAIL: at 15ns expected q=1, got %b", q);
            $finish;
        end
        #30; // 45ns
        if (q !== 1'b0) begin
            $display("SELFTEST FAIL: at 45ns expected q=0, got %b", q);
            $finish;
        end
    end
endmodule

module tb_TopModule;
