    TopModule uut (
        .clk(clk),
        .a(a),
        .q(q)
    );

    always #5 clk = ~clk;

    initial begin
        clk = 0;
        a   = 1'bx;

        // 0ns
        #5;  // 5ns: clk=1, a=0
        a = 0;

        #5;  // 10ns: clk=0, a=0

        #5;  // 15ns: clk=1, a=0
        #5;  // 20ns: clk=0, a=0

        #5;  // 25ns: clk=1, a=0
        #5;  // 30ns: clk=0, a=0

        #5;  // 35ns: clk=1, a=1
        a = 1;

        #5;  // 40ns: clk=0, a=1
        #5;  // 45ns: clk=1, a=1

        #5;  // 50ns: clk=0, a=1
        #5;  // 55ns: clk=1, a=1

        #5;  // 60ns: clk=0, a=1
        #5;  // 65ns: clk=1, a=1

        // Check values against table
        // 15ns: clk=1, a=0, q=1
        // 45ns: clk=1, a=1, q=0

        // Let's check at specific times with a small offset after posedge or directly
        // Note: non-blocking assignments update at NBA region, so at posedge time q has new value immediately after edge in simulation step.
    end

    initial begin
        #15; // at 15ns
        #0.1; // after posedge NBA update
        if (q !== 1'b1) begin
            $display("SELFTEST FAIL: at 15ns expected q=1, got %b", q);
            $finish;
        end

        #30; // at 45ns (15 + 30 = 45)
        #0.1;
        if (q !== 1'b0) begin
            $display("SELFTEST FAIL: at 45ns expected q=0, got %b", q);
            $finish;
        end

        $display("SELFTEST PASS");
        $finish;
    end
endmodule

